const input = $input.first().json;
const required = ['tenantId','automationInstanceId','eventType','occurredAt','traceId'];
const missing = required.filter((k) => input[k] === undefined || input[k] === null || input[k] === '');
if (missing.length) {
  throw new Error(`EXECUTION_TELEMETRY_INVALID_INPUT missing=${missing.join(',')}`);
}
const num = (v) => Number.isFinite(Number(v)) ? Number(v) : 0;
const event = {
  schemaVersion: '1.0',
  tenantId: String(input.tenantId),
  automationInstanceId: String(input.automationInstanceId),
  eventType: String(input.eventType),
  occurredAt: new Date(input.occurredAt).toISOString(),
  traceId: String(input.traceId),
  runId: input.runId ? String(input.runId) : null,
  engine: {
    name: input.engine?.name ? String(input.engine.name) : 'n8n',
    executionId: input.engine?.executionId ? String(input.engine.executionId) : null
  },
  status: input.status ? String(input.status) : null,
  metrics: {
    eligibleUnits: num(input.metrics?.eligibleUnits),
    automatedUnits: num(input.metrics?.automatedUnits),
    exceptionMinutes: num(input.metrics?.exceptionMinutes),
    oversightMinutes: num(input.metrics?.oversightMinutes),
    variableCost: num(input.metrics?.variableCost)
  },
  metadata: input.metadata && typeof input.metadata === 'object' ? input.metadata : {}
};
event.idempotencyKey = input.idempotencyKey
  ? String(input.idempotencyKey)
  : `${event.tenantId}:${event.automationInstanceId}:${event.traceId}:${event.eventType}`;
return [{ json: event }];
